                    owner->FinishCurrentAction();
                owner->SetCurrentAction(CCreatureAction_UnsheatheToShowToSheatheTrophy(*owner, *ParentThing, PDef->ShowTrophyAnimName));
                CTCHeroOpinionDeedLog* deed_log;
